/// The definitions of a database table.
///
/// This is implemented on the model-struct which is generated by the `#[derive(Table)]` attribute.
pub trait Table: 'static {
    /// The name of the table. This is used verbatim in the SQL queries.
    fn name(&self) -> &'static str;

    /// The columns to select when performing a `SELECT *` query on this table.
    fn selection(&self) -> &'static [&'static str];

    /// The user-defined struct representing a single row in the table.
    /// This is the struct that has the `#[derive(Table)]` applied to it.
    type Model;

    // TODO: Split all belong into new subtrait so selections can't be given to `INSERT`, `UPDATE`, `DELETE`???

    /// A struct representing a new row to be inserted into the table.
    /// This struct is generated by the `#[derive(Table)]` attribute.
    type Insert;
}
